from itertools import combinations

def solve_n(n):
    # We want to find R = {r_1, ..., r_n} and C = {c_1, ..., c_n}
    # such that R + C = {1, ..., n^2}.
    # To avoid redundancy, we can set r_1 = 0 and c_1 = 1.
    # Then r_n + c_n = n^2.
    # Since r_1 < r_2 < ... < r_n, r_n >= n-1.
    # Since c_1 < c_2 < ... < c_n, c_n >= n.
    # Also r_n + c_n = n^2, so r_n <= n^2 - n.
    # Let's iterate over all possible r_n and c_n.
    # Then we need to choose r_2, ..., r_{n-1} from {1, ..., r_n-1}
    # and c_2, ..., c_{n-1} from {2, ..., c_n-1}.
    # For each such set R and C, check if R+C = {1, ..., n^2}.

    solutions = []
    for rn in range(n-1, n**2 - n + 1):
        cn = n**2 - rn
        if cn < n:
            continue

        # Choose r_2, ..., r_{n-1}
        for R_minus_extremes in combinations(range(1, rn), n-2):
            R = sorted([0] + list(R_minus_extremes) + [rn])
            # Choose c_2, ..., c_{n-1}
            for C_minus_extremes in combinations(range(2, cn), n-2):
                C = sorted([1] + list(C_minus_extremes) + [cn])

                # Check if R+C = {1, ..., n^2}
                sums = set()
                for r in R:
                    for c in C:
                        sums.add(r + c)

                if len(sums) == n**2 and all(1 <= s <= n**2 for s in sums):
                    solutions.append((R, C))
    return solutions

