def count_solutions(n):
    total_solutions = 0
    for X in range(n-1, n**2 - n + 1):
        Y = n**2 - 1 - X
        if Y < n-1: continue

        for R_minus_extremes in combinations(range(1, X), n-2):
            R = sorted([0] + list(R_minus_extremes) + [X])
            DR_plus = set()
            for i in range(n):
                for j in range(i):
                    DR_plus.add(R[i] - R[j])

            S = set(range(1, Y + 1)) - DR_plus

            memo_C = {}
            def count_sequences(i, current_total_sum, last_suffix_sums):
                state = (i, current_total_sum, last_suffix_sums)
                if state in memo_C: return memo_C[state]
                if i == n - 1:
                    return 1 if current_total_sum == Y else 0

                res = 0
                for x in range(1, Y - current_total_sum + 1):
                    if x in S:
                        valid = True
                        new_suffix_sums = [x]
                        for s in last_suffix_sums:
                            if (x + s) not in S:
                                valid = False
                                break
                            new_suffix_sums.append(x + s)
                        if valid:
                            res += count_sequences(i + 1, current_total_sum + x, tuple(sorted(new_suffix_sums)))
                memo_C[state] = res
                return res

            total_solutions += count_sequences(0, 0, ())

    return total_solutions

